--- index.html
+++ index.html
@@ -51,9 +51,9 @@
 for(let t of targets){ctx.save();ctx.translate(t.x,t.y);ctx.rotate(t.pulse*.15);ctx.beginPath();ctx.arc(0,0,t.r+(t.pulse*5),0,7);ctx.fillStyle=t.hit?'#35405e':'#ffe58a';ctx.shadowColor=t.hit?'transparent':'#ffe58a';ctx.shadowBlur=t.hit?0:14;ctx.fill();ctx.restore()}
 // slings
 ctx.strokeStyle='#ed477f';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(W*.25,H*.67);ctx.lineTo(W*.30,H*.73);ctx.moveTo(W*.75,H*.67);ctx.lineTo(W*.70,H*.73);ctx.stroke();
 // flippers
-function flipper(x,base,ang,c){ctx.save();ctx.translate(x,base);ctx.rotate(ang);ctx.lineCap='round';ctx.strokeStyle='#090b18';ctx.lineWidth=20;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(x<W/2?75:-75,0);ctx.stroke();ctx.strokeStyle=c;ctx.lineWidth=14;ctx.stroke();ctx.restore()}flipper(W*.31,H*.88,left?.-55:-.18,'#ef3c9a');flipper(W*.69,H*.88,right?55:.18,'#46d9db');
+function flipper(x,base,ang,c){ctx.save();ctx.translate(x,base);ctx.rotate(ang);ctx.lineCap='round';ctx.strokeStyle='#090b18';ctx.lineWidth=20;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(x<W/2?75:-75,0);ctx.stroke();ctx.strokeStyle=c;ctx.lineWidth=14;ctx.stroke();ctx.restore()}flipper(W*.31,H*.88,left?-.55:-.18,'#ef3c9a');flipper(W*.69,H*.88,right?.55:.18,'#46d9db');
 // drain lane
 ctx.fillStyle='#090b18';ctx.beginPath();ctx.moveTo(W*.84,H*.72);ctx.lineTo(W*.92,H*.72);ctx.lineTo(W*.92,H);ctx.lineTo(W*.76,H);ctx.closePath();ctx.fill();ctx.strokeStyle='#4f5fa5';ctx.lineWidth=5;ctx.stroke();
 // ball trail
 if(ball){for(let i=ball.trail.length-1;i>=0;i--){let p=ball.trail[i];ctx.globalAlpha=(ball.trail.length-i)/ball.trail.length*.18;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(p.x,p.y,ball.r*(1-i/12),0,7);ctx.fill()}ctx.globalAlpha=1;ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,7);let g=ctx.createRadialGradient(ball.x-3,ball.y-4,1,ball.x,ball.y,10);g.addColorStop(0,'#fff');g.addColorStop(.35,'#dce4ff');g.addColorStop(1,'#6677a5');ctx.fillStyle=g;ctx.shadowColor='#fff';ctx.shadowBlur=10;ctx.fill();ctx.shadowBlur=0}
